package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateProof {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ProofRequest request, Out<ProofRequest> body, Settings settings)
            throws ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        body.set(request);
    }
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/proof: who adds a proof to the claim. */
public record ProofRequest(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one; not a SETTLED or VOID claim, nor one dated inside a closed period. */
public class ApplyProof {
    public void apply(@Val ProofRequest request, @Val Claim claim, Periods periods) throws ClaimStatusRefusedException {
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ClaimStatusRefusedException("A " + claim.getStatus() + " claim cannot take a proof");
        }
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can take a proof");
        }
        claim.setProofs(claim.getProofs() + 1);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveProof {
    public void save(@Val Claim claim, Claims claims) {
        claims.proofs(claim);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods, People people, Claims claims)
            throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            // Only a draft can be edited; to change an open claim, void it and add a new one.
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getDate()) || periods.isClosed(claim.getSheetId(), date)) {
            throw new InvalidClaimException("No claim dated inside a closed period can be edited");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
        claim.setAmount(request.amount());
        claim.setCorrects(request.corrects());
        claim.setCorrectedDate(claims.correctedDate(claim.getSheetId(), claim.getPersonId(), request.corrects()));
        claim.setDate(date);
        claim.setNote(request.note());
    }
}
