import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimStatusRefused {
    public void handle(@Parameter ClaimStatusRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow; nothing is written. */
public class ClaimStatusRefusedException extends Exception {
    public ClaimStatusRefusedException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to);
    }

    public ClaimStatusRefusedException(String message) {
        super(message);
    }
}
